// Prepare context for AI calls
const yacht = $('Get Yacht Data').first().json;
const assets = $('Get Yacht Assets').all().map(a => a.json);

// Summarize asset tags
const tagCounts = {};
assets.forEach(a => {
  const tag = a.tag || 'untagged';
  tagCounts[tag] = (tagCounts[tag] || 0) + 1;
});

const yachtProfile = {
  yacht_id: yacht.yacht_id,
  title: yacht.title,
  name: yacht.name,
  length_ft: yacht.length_ft,
  year: yacht.year,
  manufacturer: yacht.manufacturer,
  model: yacht.model,
  location: yacht.location,
  capacity: yacht.capacity,
  crew: yacht.crew,
  amenities: yacht.amenities || [],
  experiences: yacht.experiences || [],
  highlights: yacht.highlights || [],
  prices: yacht.prices
};

return [{
  json: {
    yacht: yachtProfile,
    assets: assets,
    assetTags: tagCounts,
    assetCount: assets.length,
    videoCount: assets.filter(a => a.type === 'video').length,
    photoCount: assets.filter(a => a.type === 'photo').length
  }
}];

