// Parse and merge AI responses
const claudeRaw = $('Claude: Creative Director').first().json;
const openaiRaw = $('OpenAI: Performance Marketer').first().json;
const context = $('Prepare AI Context').first().json;

// Parse Claude response
let creative = {};
try {
  const claudeText = claudeRaw.content?.[0]?.text || '{}';
  creative = JSON.parse(claudeText);
} catch (e) {
  creative = { error: 'Failed to parse Claude response', raw: claudeRaw };
}

// Parse OpenAI response  
let performance = {};
try {
  const openaiText = openaiRaw.choices?.[0]?.message?.content || '{}';
  performance = JSON.parse(openaiText);
} catch (e) {
  performance = { error: 'Failed to parse OpenAI response', raw: openaiRaw };
}

// Merge into Content Pack
const contentPack = {
  yacht_id: context.yacht.yacht_id,
  generated_at: new Date().toISOString(),
  yacht_profile: context.yacht,

  // From Claude
  creative_angles: creative.creative_angles || [],
  scripts: creative.scripts || [],
  on_screen_text_sets: creative.on_screen_text_sets || [],
  hooks_premium: creative.hooks_premium || [],

  // From OpenAI
  hooks: performance.hooks || [],
  captions: performance.captions || [],
  cta_variations: performance.cta_variations || [],
  hashtag_sets: performance.hashtag_sets || [],

  // Meta
  asset_count: context.assetCount,
  status: 'draft'
};

return [{ json: contentPack }];

