// Process QA review and prepare final output
const contentPack = $('Merge AI Responses').first().json;
const qaRaw = $input.first().json;

let qa = { status: 'approved', issues: [], brand_score: 8, compliance_score: 8 };
try {
  const qaText = qaRaw.content?.[0]?.text || '{}';
  qa = JSON.parse(qaText);
} catch (e) {
  qa.parse_error = true;
}

// Apply auto-fixes for non-critical issues
let finalContent = { ...contentPack };

if (qa.status === 'needs_revision' && qa.issues) {
  const criticalIssues = qa.issues.filter(i => i.severity === 'critical');

  if (criticalIssues.length === 0) {
    // Auto-apply suggested fixes
    qa.issues.forEach(issue => {
      if (issue.suggested_fix && issue.original) {
        // Simple string replacement in captions/hooks
        finalContent.captions = finalContent.captions?.map(c => ({
          ...c,
          caption: c.caption?.replace(issue.original, issue.suggested_fix)
        }));
      }
    });
    qa.status = 'auto_fixed';
  }
}

return [{
  json: {
    content_pack: finalContent,
    qa_result: qa,
    final_status: qa.status === 'approved' || qa.status === 'auto_fixed' ? 'ready' : 'needs_review'
  }
}];
